//! Shared golden loader. Expected XML is raw reference output, never regenerated by tests.
use bc_core::{
    encoding::{self, BomPolicy, Encoding},
    DiffKind,
};
use quick_xml::{
    events::{BytesStart, Event},
    Reader,
};
use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExpectedRow {
    pub left: Option<usize>,
    pub right: Option<usize>,
    pub kind: DiffKind,
    pub importance: u8,
}
#[derive(Debug, Clone)]
pub struct Case {
    pub name: String,
    pub directory: PathBuf,
    pub properties: BTreeMap<String, String>,
}
impl Case {
    pub fn flag(&self, key: &str) -> bool {
        self.properties.get(key).is_some_and(|v| v == "true")
    }
    pub fn property(&self, key: &str, default: &str) -> String {
        self.properties
            .get(key)
            .map_or_else(|| default.into(), Clone::clone)
    }
    pub fn input(&self, side: &str) -> Result<Vec<u8>, String> {
        let source = std::fs::read_to_string(self.directory.join(format!("{side}.txt")))
            .map_err(|e| e.to_string())?;
        let source = source.replace("\r\n", "\n").replace('\r', "\n");
        let style = self.property(&format!("{side}_ending"), "lf");
        let mut text = String::new();
        for (i, line) in source.split_inclusive('\n').enumerate() {
            if let Some(line) = line.strip_suffix('\n') {
                text.push_str(line);
                text.push_str(match style.as_str() {
                    "lf" => "\n",
                    "crlf" => "\r\n",
                    "cr" => "\r",
                    "cycle" => ["\r\n", "\n", "\r"][i % 3],
                    _ => return Err("unknown ending policy".into()),
                });
            } else {
                text.push_str(line);
            }
        }
        let encoding = self.encoding(side)?;
        encoding::encode(
            &text,
            encoding,
            BomPolicy::Preserve,
            self.flag(&format!("{side}_bom")),
        )
        .map_err(|e| e.to_string())
    }
    pub fn encoding(&self, side: &str) -> Result<Encoding, String> {
        Ok(
            match self.property(&format!("{side}_encoding"), "utf8").as_str() {
                "utf8" => Encoding::Utf8,
                "utf16le" => Encoding::Utf16Le,
                "utf16be" => Encoding::Utf16Be,
                "936" => Encoding::CodePage(936),
                "1252" => Encoding::CodePage(1252),
                _ => return Err("unknown fixture encoding".into()),
            },
        )
    }
    pub fn expected(&self, strategy: &str) -> Result<Vec<ExpectedRow>, String> {
        let xml = std::fs::read_to_string(self.directory.join(format!("expected.{strategy}.xml")))
            .map_err(|e| format!("{} {strategy}: {e}", self.name))?;
        parse_report(&xml)
    }
}
pub fn corpus(root: &Path) -> Result<Vec<Case>, String> {
    if !root.exists() {
        return Ok(Vec::new());
    }
    let mut cases = Vec::new();
    for entry in std::fs::read_dir(root).map_err(|e| e.to_string())? {
        let directory = entry.map_err(|e| e.to_string())?.path();
        if !directory.is_dir() || !directory.join("case.properties").exists() {
            continue;
        }
        let source = std::fs::read_to_string(directory.join("case.properties"))
            .map_err(|e| e.to_string())?;
        let mut properties = BTreeMap::new();
        for line in source
            .lines()
            .map(str::trim)
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
        {
            let (key, value) = line.split_once('=').ok_or("bad case property")?;
            if properties.insert(key.into(), value.into()).is_some() {
                return Err("duplicate case property".into());
            }
        }
        cases.push(Case {
            name: directory
                .file_name()
                .unwrap()
                .to_string_lossy()
                .into_owned(),
            directory,
            properties,
        });
    }
    cases.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(cases)
}
/// Only an entirely absent oracle corpus skips. Partially generated corpora fail.
pub fn has_expectations(cases: &[Case]) -> Result<bool, String> {
    let count = cases
        .iter()
        .flat_map(|case| {
            [
                case.directory.join("expected.myers.xml"),
                case.directory.join("expected.standard.xml"),
            ]
        })
        .filter(|p| p.exists())
        .count();
    if count == 0 {
        return Ok(false);
    }
    if count != cases.len() * 2 {
        return Err(format!(
            "incomplete oracle corpus: {count}/{} reports",
            cases.len() * 2
        ));
    }
    Ok(true)
}
fn attribute(node: &BytesStart<'_>, name: &[u8]) -> Result<Option<String>, String> {
    for attr in node.attributes() {
        let attr = attr.map_err(|e| e.to_string())?;
        if attr.key.as_ref() == name {
            return Ok(Some(
                quick_xml::escape::unescape(
                    std::str::from_utf8(&attr.value).map_err(|e| e.to_string())?,
                )
                .map_err(|e| e.to_string())?
                .into_owned(),
            ));
        }
    }
    Ok(None)
}
fn index(value: Option<String>) -> Result<Option<usize>, String> {
    value
        .map(|v| {
            v.parse::<usize>()
                .map_err(|e| e.to_string())?
                .checked_sub(1)
                .ok_or("line numbers must be positive".into())
        })
        .transpose()
}
pub fn parse_report(xml: &str) -> Result<Vec<ExpectedRow>, String> {
    let mut reader = Reader::from_str(xml);
    let mut rows = Vec::new();
    let mut active = None;
    let mut left = None;
    let mut right = None;
    let mut saw_comparison = false;
    loop {
        match reader.read_event().map_err(|e| e.to_string())? {
            Event::Start(node) if node.name().as_ref() == b"filecomparison" => {
                saw_comparison = true
            }
            Event::Empty(node) if node.name().as_ref() == b"filecomparison" => {
                saw_comparison = true
            }
            Event::Start(node) if node.name().as_ref() == b"linecomp" => {
                if active.is_some() {
                    return Err("nested linecomp".into());
                }
                active = Some(attribute(&node, b"status")?.ok_or("missing linecomp status")?);
                left = None;
                right = None;
            }
            Event::Start(node) | Event::Empty(node)
                if node.name().as_ref() == b"text" && active.is_some() =>
            {
                if let Some(i) = index(attribute(&node, b"ltid")?)? {
                    if left.replace(i).is_some() {
                        return Err("multiple left lines in one linecomp".into());
                    }
                }
                if let Some(i) = index(attribute(&node, b"rtid")?)? {
                    if right.replace(i).is_some() {
                        return Err("multiple right lines in one linecomp".into());
                    }
                }
            }
            Event::End(node) if node.name().as_ref() == b"linecomp" => {
                let status = active.take().ok_or("unexpected linecomp end")?;
                let importance = match status.as_str() {
                    "same" => 0,
                    "similar" | "unimportant" | "leftsimilar" | "rightsimilar" => 1,
                    "different" | "left orphan" | "right orphan" | "leftorphan" | "rightorphan" => {
                        2
                    }
                    _ => return Err(format!("unknown linecomp status {status:?}")),
                };
                let kind = match (left, right) {
                    (Some(_), Some(_)) => {
                        if importance == 0 {
                            DiffKind::Same
                        } else {
                            DiffKind::Changed
                        }
                    }
                    (Some(_), None) => DiffKind::LeftOnly,
                    (None, Some(_)) => DiffKind::RightOnly,
                    _ => return Err("linecomp contains no line indices".into()),
                };
                rows.push(ExpectedRow {
                    left,
                    right,
                    kind,
                    importance,
                });
            }
            Event::Eof => break,
            _ => {}
        }
    }
    if !saw_comparison || active.is_some() {
        return Err("incomplete text report".into());
    }
    let mut l = 0;
    let mut r = 0;
    for row in &rows {
        if let Some(i) = row.left {
            if i != l {
                return Err("left report lines out of order".into());
            }
            l += 1;
        }
        if let Some(i) = row.right {
            if i != r {
                return Err("right report lines out of order".into());
            }
            r += 1;
        }
    }
    Ok(rows)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn parses_captured_unimportant_pair_and_orphan_statuses() {
        let orphan = parse_report(include_str!(
            "../../../../../tools/golden/evidence/014-standard-default.xml"
        ))
        .unwrap();
        assert_eq!(orphan[1].kind, DiffKind::LeftOnly);
        assert_eq!(orphan[1].importance, 1);
        let paired = parse_report(include_str!(
            "../../../../../tools/golden/evidence/016-standard-default.xml"
        ))
        .unwrap();
        assert_eq!(paired[1].kind, DiffKind::Changed);
        assert_eq!(paired[1].importance, 1);
    }

    #[test]
    fn parses_observed_reference_schema_and_empty_corpus() {
        let xml = r#"<bcreport><filecomparison><linecomp status="same"><text ltid="1" rtid="1">anchor</text></linecomp><linecomp status="different"><text ltid="2">value old</text><text rtid="2">value new</text></linecomp></filecomparison></bcreport>"#;
        let rows = parse_report(xml).unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[1].kind, DiffKind::Changed);
        assert!(parse_report("<bcreport/>").is_err());
        assert!(!has_expectations(&[]).unwrap());
        let path = std::env::temp_dir().join(format!(
            "matcha-empty-oracle-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        assert!(corpus(&path).unwrap().is_empty());
    }
}
